fn layout(app: &Studio, t: &Theme) -> View<Msg> {
    let tabs = tabview(["Design", "Build", "Ship"], app.tab)
        .style(full(180))
        .children(
            [
                "Shape the interface.",
                "Connect your application.",
                "Make it your own.",
            ]
            .iter()
            .map(|s| {
                studio_column()
                    .style(Style::default().pad(20))
                    .child(styled_label(s, t.text, Font::montserrat_20()))
            }),
        )
        .on_value_changed(Msg::Tab);
    let tiles = tileview(
        [
            Tile::new(0, 0, ScrollDir::RIGHT),
            Tile::new(1, 0, ScrollDir::LEFT),
        ],
        app.tile,
    )
    .style(full(138))
    .children([
        studio_column()
            .style(Style::default().bg(TEAL).pad(20))
            .child(styled_label("01 / Explore", WHITE, Font::montserrat_20())),
        studio_column()
            .style(Style::default().bg(BLUE).pad(20))
            .child(styled_label("02 / Create", WHITE, Font::montserrat_20())),
    ])
    .on_value_changed(Msg::Tile);
    let grid = grid(
        [GridTrack::Fr(1), GridTrack::Fr(1)],
        [GridTrack::Fr(1), GridTrack::Fr(1)],
        (0..4).map(|i| {
            action_button(&format!("Cell {}", i + 1), Msg::Click, t)
                .key(Key::Id(400 + i))
                .grid_cell((i % 2) as u16, (i / 2) as u16, 1, 1)
                .grid_align(GridAlign::Stretch, GridAlign::Stretch)
                .style(Style::default().bg(if i == 0 { ORANGE } else { t.background }))
        }),
    )
    .style(full(142).gap(12))
    .grid_navigation(GridNavigation::default());
    studio_column()
        .child(
            studio_row().children([
                half(
                    card(
                        "One space, three tabs",
                        "Native tabview / controlled selection",
                        t,
                    ),
                    308,
                )
                .child(tabs),
                half(
                    card(
                        "Swipe to the next idea",
                        "Native tileview / touch or button",
                        t,
                    ),
                    308,
                )
                .child(tiles)
                .child(action_button(
                    "Next tile",
                    Msg::Tile((1 - app.tile) as i32),
                    t,
                )),
            ]),
        )
        .child(
            studio_row().children([
                half(
                    card("A flexible grid", "Arrow-key navigation / equal tracks", t),
                    254,
                )
                .child(grid),
                half(
                    card(
                        "Flex, with intention",
                        "Rows / columns / nested surfaces",
                        t,
                    ),
                    254,
                )
                .child(
                    studio_row().children([
                        studio_column()
                            .style(
                                Style::default()
                                    .width(Size::Percent(30))
                                    .height(Size::Px(140))
                                    .bg(TEAL)
                                    .radius(10)
                                    .pad(16),
                            )
                            .child(styled_label("Side", WHITE, t.body_font)),
                        studio_column()
                            .style(Style::default().flex_grow(1).gap(12))
                            .children(["Header", "Content", "Footer"].iter().map(|name| {
                                obj().style(full(38).bg(t.background).radius(8)).child(
                                    text(name, t).style(Style::default().align(Align::Center)),
                                )
                            })),
                    ]),
                ),
            ]),
        )
}

const fn tile_pixels(alternate: bool) -> [u8; 72 * 72 * 2] {
    let mut pixels = [0u8; 72 * 72 * 2];
    let mut y = 0;
    while y < 72 {
        let mut x = 0;
        while x < 72 {
            let dx = x as i32 - 36;
            let dy = y as i32 - 36;
            let (r, g, b) = if dx * dx + dy * dy < 25 * 25 {
                if alternate {
                    (91u16, 117u16, 218u16)
                } else {
                    (225, 88, 47)
                }
            } else if x % 12 < 1 || y % 12 < 1 {
                (208, 222, 211)
            } else {
                (234, 241, 231)
            };
            let value = ((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3);
            let index = (y * 72 + x) * 2;
            pixels[index] = value as u8;
            pixels[index + 1] = (value >> 8) as u8;
            x += 1;
        }
        y += 1;
    }
    pixels
}
static TILE_A: [u8; 72 * 72 * 2] = tile_pixels(false);
static TILE_B: [u8; 72 * 72 * 2] = tile_pixels(true);

fn canvas_page(t: &Theme) -> View<Msg> {
    let mut frame = Canvas::new(940, 205).background(INK, 255);
    for x in (20..940).step_by(40) {
        frame = frame.draw(DrawCommand::Line {
            from: (x, 20),
            to: (x, 185),
            width: 1,
            color: Color::rgb(43, 53, 67),
            opacity: 255,
        });
    }
    for y in (25..205).step_by(40) {
        frame = frame.draw(DrawCommand::Line {
            from: (20, y),
            to: (920, y),
            width: 1,
            color: Color::rgb(43, 53, 67),
            opacity: 255,
        });
    }
    for x in 1..890_i16 {
        let y = |v: i16| (110.0 + (f32::from(v) / 68.0).sin() * 43.0) as i16;
        frame = frame.draw(DrawCommand::Line {
            from: (x + 20, y(x - 1)),
            to: (x + 21, y(x)),
            width: 3,
            color: ORANGE,
            opacity: 255,
        });
    }
    frame = frame
        .draw(DrawCommand::Rect {
            x: 38,
            y: 28,
            width: 138,
            height: 34,
            radius: 8,
            color: TEAL,
            opacity: 255,
        })
        .draw(DrawCommand::Text {
            x: 50,
            y: 36,
            width: 120,
            height: 24,
            text: "CANVAS / LIVE".into(),
            font: t.body_font,
            color: WHITE,
            opacity: 255,
        })
        .draw(DrawCommand::Pixel {
            x: 20,
            y: 20,
            color: WHITE,
            opacity: 255,
        });
    studio_column()
        .child(
            card(
                "Your pixels, your rules",
                "Lines / rounded rectangles / text / pixels",
                t,
            )
            .style(full(315))
            .child(rs_lvgl_ui::canvas(frame)),
        )
        .child(
            studio_row().children([
                third(card("Curved type", "Arc label", t), 248).child(
                    arc_label("RUST / LVGL", 48, 200, 160).style(
                        Style::default()
                            .width(Size::Px(200))
                            .height(Size::Px(130))
                            .fg(TEAL)
                            .font(Font::montserrat_16()),
                    ),
                ),
                third(
                    card("Native motion", "Scoped animation / reversible", t),
                    248,
                )
                .child(
                    obj().style(full(110)).scrollable(false).child(
                        obj()
                            .style(
                                Style::default()
                                    .width(Size::Px(42))
                                    .height(Size::Px(42))
                                    .bg(ORANGE)
                                    .radius(12)
                                    .align(Align::LeftMid),
                            )
                            .animate(
                                Animation::new(AnimationProperty::X, 12, 200, 1400)
                                    .reverse(1400)
                                    .repeat(u32::MAX)
                                    .easing(Easing::EaseInOut),
                            ),
                    ),
                ),
                third(
                    card("Custom lifecycle", "Rust widget / tick / cleanup", t),
                    248,
                )
                .child(custom(super::native::Pulse::default()))
                .child(action_button("Try a toast", Msg::Toast, t)),
            ]),
        )
}

fn composition(app: &Studio, t: &Theme) -> View<Msg> {
    let list = list::list(
        t,
        [
            ListItem::new("Studio workspace")
                .detail("Your components in one place")
                .on_click(Msg::Click)
                .view(t),
            ListItem::new("Device settings")
                .detail("Open the next page")
                .chevron(true)
                .on_click(Msg::Push)
                .view(t),
        ],
    )
    .style(full(136));
    let files = file_explorer::view(
        t,
        "/studio/assets",
        Some(Msg::File(0)),
        [
            FileEntry::directory(1, "Animations", Msg::File(1)),
            FileEntry::file(2, "studio-motion.json", Msg::File(2)),
            FileEntry::file(3, "status.gif", Msg::File(3)),
        ],
    )
    .style(full(160));
    studio_column()
        .child(
            studio_row().children([
                half(
                    Panel::new("Your workspace")
                        .action(action_button("Details", Msg::Push, t))
                        .child(list)
                        .view(t),
                    268,
                )
                .style(Style::default().radius(16)),
                half(
                    card(
                        "Files, without surprises",
                        "Application-provided sample entries",
                        t,
                    ),
                    278,
                )
                .child(files),
            ]),
        )
        .child(
            studio_row().children([
                half(
                    card("Go a little deeper", "Stack navigation / back behavior", t),
                    306,
                )
                .child(
                    nav::view(
                        &app.nav,
                        t,
                        *app.nav.current(),
                        studio_column()
                            .child(
                                text(
                                    if app.nav.can_go_back() {
                                        "A nested page. Back returns to the workspace."
                                    } else {
                                        "Start with a page, then push another."
                                    },
                                    t,
                                )
                                .style(Style::default().width(Size::Percent(100))),
                            )
                            .child(action_button(
                                if app.nav.can_go_back() {
                                    "Back to workspace"
                                } else {
                                    "Open device"
                                },
                                if app.nav.can_go_back() {
                                    Msg::Back
                                } else {
                                    Msg::Push
                                },
                                t,
                            )),
                        Msg::Back,
                    )
                    .style(full(164)),
                ),
                half(
                    card("A moment of attention", "Message box / modal / toast", t)
                        .style(Style::default().gap(10)),
                    306,
                )
                .child(
                    msgbox("Everything is ready.")
                        .msgbox_title("Workspace prepared")
                        .msgbox_buttons(["Got it"])
                        .style(full(140))
                        .on_value_changed(|_| Msg::Toast),
                )
                .child(studio_row().style(Style::default().pad(6)).children([
                    primary("Open dialog", Msg::Dialog(true), t),
                    action_button("Show toast", Msg::Toast, t),
                ])),
            ]),
        )
}

//! Native-only samples, bounded by the mounted custom node's lifetime.
use super::*;
use rs_lvgl::NativeObject;

pub(super) fn view(app: &Studio, t: &Theme) -> View<Msg> {
    let mut samples = Vec::new();
    for (kind, title, caption) in [
        (0, "Native list", "Select a sample action"),
        (1, "Native menu", "Open Display, then use Back"),
        (2, "Native window", "Header / content / action"),
    ] {
        // SAFETY: each factory returns a direct child of the supplied parent.
        // All descendants and native menu callbacks are owned by that subtree;
        // strings are static or copied by LVGL. No pointers escape the factory.
        let sample = unsafe { raw(move |parent| {
            let obj = match kind {
                0 => rs_lvgl_sys::lv_list_create(parent.as_ptr()),
                1 => rs_lvgl_sys::lv_menu_create(parent.as_ptr()),
                _ => rs_lvgl_sys::lv_win_create(parent.as_ptr()),
            };
            let object = NonNull::new(obj)?;
            rs_lvgl_sys::lv_obj_set_size(obj, rs_lvgl_sys::lv_pct(100), 306);
            match kind {
                0 => {
                    rs_lvgl_sys::lv_list_add_text(obj, c"STUDIO COLLECTION".as_ptr().cast());
                    for name in [c"New workspace", c"Open a sample", c"Save a preset", c"Export a snapshot"] {
                        rs_lvgl_sys::lv_list_add_button(obj, core::ptr::null(), name.as_ptr().cast());
                    }
                }
                1 => {
                    let page = rs_lvgl_sys::lv_menu_page_create(obj, c"Device".as_ptr().cast());
                    let details = rs_lvgl_sys::lv_menu_page_create(obj, c"Display".as_ptr().cast());
                    let settings = rs_lvgl_sys::lv_menu_cont_create(page);
                    let label = rs_lvgl_sys::lv_label_create(settings);
                    rs_lvgl_sys::lv_label_set_text(label, c"Display  >".as_ptr().cast());
                    let label = rs_lvgl_sys::lv_label_create(details);
                    rs_lvgl_sys::lv_label_set_text(label, c"1280 x 860\nRGB color\nNative rendering".as_ptr().cast());
                    rs_lvgl_sys::lv_menu_set_load_page_event(obj, settings, details);
                    rs_lvgl_sys::lv_menu_set_page(obj, page);
                }
                _ => {
                    rs_lvgl_sys::lv_win_add_title(obj, c"Sample device".as_ptr().cast());
                    rs_lvgl_sys::lv_win_add_button(obj, c"\u{f067}".as_ptr().cast(), 42);
                    let label = rs_lvgl_sys::lv_label_create(rs_lvgl_sys::lv_win_get_content(obj));
                    rs_lvgl_sys::lv_label_set_text(label, c"A native window.\n\nComposed inside a Rust view.\n\nPress the header action.".as_ptr().cast());
                }
            }
            enable_bubbling(obj);
            Some(object)
        }) }.key(Key::Id(700 + kind + if app.dark { 10 } else { 0 }))
    ;
        samples.push(
            card(title, caption, t)
                .style(
                    Style::default()
                        .width(Size::Percent(32))
                        .height(Size::Px(430)),
                )
                .child(sample)
                .on_bubbled_event(|event| {
                    matches!(
                        event,
                        InputEvent::Other(Event::Clicked)
                            | InputEvent::Pointer(PointerEvent {
                                event: Event::Clicked,
                                ..
                            })
                    )
                    .then_some(Msg::Click)
                }),
        );
    }
    studio_column().child(studio_row().children(samples))
        .child(card("One native provider. Three ways to build.", "Typed views / imperative widgets / raw C bindings",t).style(Style::default().height(Size::Px(128)))
            .child(text(&format!("{} native actions received. Native samples keep their children and callbacks inside one mounted subtree.",app.clicks),t)
                .style(Style::default().width(Size::Percent(100)))))
}

#[derive(Default)]
pub(super) struct Pulse {
    elapsed: u32,
}
impl CustomWidget for Pulse {
    fn create(&mut self, parent: &mut rs_lvgl::Obj<'_>) -> Result<CustomObject, UiError> {
        // SAFETY: the reconciler supplies a live parent. The new direct child
        // is returned to the reconciler; this widget retains no raw pointer.
        unsafe {
            let raw = NonNull::new(rs_lvgl_sys::lv_obj_create(parent.raw().as_ptr()))
                .ok_or(UiError::Allocation)?;
            rs_lvgl_sys::lv_obj_set_size(raw.as_ptr(), 52, 52);
            rs_lvgl_sys::lv_obj_set_style_radius(raw.as_ptr(), 26, 0);
            rs_lvgl_sys::lv_obj_set_style_border_width(raw.as_ptr(), 0, 0);
            rs_lvgl_sys::lv_obj_set_style_bg_color(
                raw.as_ptr(),
                rs_lvgl_sys::lv_color_t {
                    red: 26,
                    green: 145,
                    blue: 128,
                },
                0,
            );
            CustomObject::new(parent, raw)
        }
    }
    fn update(&mut self, object: &mut CustomObject, elapsed_ms: u32) -> Result<(), UiError> {
        self.elapsed = self.elapsed.wrapping_add(elapsed_ms);
        let phase = (self.elapsed % 1600) as f32 / 1600.0 * std::f32::consts::TAU;
        let opacity = (185.0 + 70.0 * phase.sin()) as u8;
        // SAFETY: the handle is borrowed for this hook and stays on the UI thread.
        unsafe {
            rs_lvgl_sys::lv_obj_set_style_opa(object.raw().as_ptr(), opacity, 0);
        }
        Ok(())
    }
    fn delete(&mut self, _: &mut CustomObject) {
        self.elapsed = 0;
    }
}

/// Enable event forwarding within a newly created subtree.
///
/// # Safety
/// The caller must supply a live subtree on the LVGL thread, with no concurrent
/// deletion. No pointer escapes; recursion touches only current descendants.
unsafe fn enable_bubbling(root: *mut rs_lvgl_sys::lv_obj_t) {
    unsafe {
        rs_lvgl_sys::lv_obj_set_event_bubble(root, true);
        for i in 0..rs_lvgl_sys::lv_obj_get_child_count(root) {
            enable_bubbling(rs_lvgl_sys::lv_obj_get_child(root, i as i32));
        }
    }
}
